			if (guards == 0)
				return expected;

			if (others > 0)
			{
				var kept = new string[expected.Length - guards];
				var at   = 0;

				for (var i = 0; i < expected.Length; i++)
					if (expected[i].Length == 0 || expected[i][0] != '\u0002')
						kept[at++] = expected[i];

				return kept;
			}

			// A guard written with its own words (`when @(…) on fail "…"`) says them, as a rule's
			// `on fail` does: the author took the wording, and it is the whole answer.
			for (var i = 0; i < expected.Length; i++)
